/* 0026_assumed_niche_rates.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
alter table public.website_niche_costs add column if not exists assumed boolean not null default false;
comment on column public.website_niche_costs.assumed is 'True when this is the publishers sensitive rate applied to a topic they never mentioned, rather than a price they quoted. Priced off, but never reported as a quote.';
insert into public.website_niche_costs (website_id, niche, link_type, cost_minor, assumed, updated_by) select policy.website_id, policy.niche, quoted.link_type, quoted.rate, true, 'migration 0026' from public.website_niche_policy as policy join public.websites as site on site.id = policy.website_id join lateral ( select existing.link_type, max(existing.cost_minor) as rate from public.website_niche_costs as existing where existing.website_id = policy.website_id and existing.assumed = false group by existing.link_type ) as quoted on true where policy.accepted = 'unknown' and policy.niche = any (site.accepted_niches) and site.status <> 'archived' and not exists ( select 1 from public.website_niche_costs as own where own.website_id = policy.website_id and own.niche = policy.niche and own.link_type = quoted.link_type ) on conflict (website_id, niche, link_type) do nothing;
